#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static void url_decode(const char *src, char *dst) {
    while (*src) {
        if (*src == '+') {
            *dst++ = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            char hex[3] = { src[1], src[2], '\0' };
            *dst++ = (char)strtol(hex, NULL, 16);
            src += 3;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

int main(void) {
    char line[2048];
    char key[2048];
    char val[2048];
    if (!fgets(line, sizeof(line), stdin)) {
        puts("NO_INPUT");
        return 0;
    }
    // Remove trailing newline and carriage return if present
    size_t len = strlen(line);
    while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
    }
    char *pair = line;
    while (pair) {
        char *amp = strchr(pair, '&');
        if (amp) *amp = '\0';
        char *eq = strchr(pair, '=');
        if (eq) {
            *eq = '\0';
            url_decode(pair, key);
            url_decode(eq+1, val);
        } else {
            url_decode(pair, key);
            val[0] = '\0';
        }
        printf("%s=%s\n", key, val);
        if (amp) {
            pair = amp + 1;
        } else {
            break;
        }
    }
    return 0;
}
